  const order=[0,1,2].map(i=>pal[(i+h)%pal.length]);const cuts=[SJ0,SJ0+Math.round(span*(.34+((h>>4)%10)*.012)),SJ0+Math.round(span*(.68+((h>>8)%10)*.01)),SJ1];
