  kAdd(new THREE.TorusGeometry(2.62,.13,8,48),copper,-2.4,2.42,0,S,Math.PI/2,0,0,1.02,.92,1);
  /* arched mouth: brick arch, iron door frame, hinged door ajar, embers inside */
