  hw.forEach((w,i)=>{const sp=new THREE.Group();sp.position.set(w.c[0],w.c[1],w.c[2]);const m=new THREE.Mesh(cg['w'+i],SH.carVC);sp.add(m);g.add(sp);wh.push({sp,r:w.r});});
