  const rim=new THREE.DirectionalLight('#9fd0ff',1.6);rim.position.set(-8,6,-10);ps.add(rim);const warm=new THREE.PointLight('#ffb070',1.2,40);warm.position.set(6,2,8);ps.add(warm);
