  const plM=new THREE.MeshStandardMaterial({color:'#e2b06a',roughness:.75}),saM=new THREE.MeshStandardMaterial({color:'#b8321d',roughness:.45}),chM=new THREE.MeshStandardMaterial({color:'#f6d36b',roughness:.4});
