  {const mv=(CFG.mvol==null?45:CFG.mvol)/100,race=state==='race'||state==='countdown'||state==='intro';MUS.bus.gain.setTargetAtTime(mv*(state==='paused'?.3:state==='loading'?.55:race?.62:.95),ac.currentTime,.15);}
