(()=>{try{const f=document.getElementById('fpsEl'),st=document.getElementById('tbProg')||document.getElementById('stage');if(f&&st)st.appendChild(f);}catch(e){}})();
/* ================= MULTIPLAYER: play with up to 3 friends =================
   One phone hosts. The host runs the real race (every kart, the rivals, items, boxes, hits and places) and treats each
   friend's kart as driven by that friend's buttons. A guest drives its own kart locally so steering is instant, replays
   its recent inputs on top of every correction from the host, and shows everything else exactly as the host sends it.
   Phones find each other through a short room code over a relay server; the race data uses a direct link when one opens. */
const NET={role:null,code:'',peer:null,conns:[],me:0,pl:[],cfg:null,fromNet:false,loaded:new Set(),tick:0,seq:0,hist:[],outQ:[],inQ:{},inS:{},inLast:{},ack:{},
  snaps:[],mir:new Map(),mirH:new Map(),mirList:[],fxQ:[],nid:0,inUpd:false,finSeen:false,lastRecv:0,goT:0,waitTimer:0,replay:false,abQ:false,relay:null,lastFl:0,unack:[],ackRx:0};
const NET_PROTO=104;/* bump when race messages or kart physics change: friends on different versions would drive differently */
const NET_SLOTS=[4,3,5,2],NET_ALPHA='ABCDEFGHJKMNPQRSTUVWXYZ23456789';
const netId=c=>'crustrush-v1-'+c.toUpperCase();
const NET_REM=['x','y','a','ma','z','wy','speed','steer','drift','charge','boost','spin','air','glide','loopTh','onRamp','rush','shL','shield','mzH','sink','sinkT','trickK','trickT','frozen','acc','brake','dAmt','fx','prog','finished','place','finishTime','inv','big','ghostT','shrinkT','absT','idx','gRings','trick','bPk','fTier','megaT','pestoT','flatT','chiliT','oilT','burnT','est','oliveT'];
const NET_SKIP=new Set(['px','py','pa','pma','pz','pwy','pth','rx','ry','rz','rg','rma','rth','isPlayer','auto','ri','netId','cox','coy','coz','coth','sf','col','stall','vl','nst']);
const NET_ANG=new Set(['a','ma']),NET_POS=new Set(['x','y','z','wy','loopTh','speed','charge','steer','prog']);
/* compact kart records: the first 8 fields always, then only the fields that differ from their resting value, as [index,value] pairs
   (a resting kart field is 0, false or null); the receiver rebuilds the full row, so everything downstream is unchanged */
const NET_ZB=new Set(['air','glide','onRamp','finished','big','trick','est']),NET_ZN=new Set(['shL','sink','sinkT','trickK','dAmt','ghostT','shrinkT','absT','bPk','fTier','megaT','pestoT','flatT','chiliT','oilT','burnT','oliveT']);
let NET_Z=null;const netZ=()=>NET_Z||(NET_Z=NET_REM.map(f=>NET_ZB.has(f)?false:NET_ZN.has(f)?null:0));
function netKEnc(v){const Z=netZ(),o=v.slice(0,8);for(let j=8;j<v.length;j++){let x=v[j];if(x===undefined)x=null;if(x!==Z[j])o.push(j,x);}return o;}
function netKDec(a){const v=netZ().slice();for(let j=0;j<8;j++)v[j]=a[j];for(let i=8;i+1<a.length;i+=2)v[a[i]]=a[i+1];return v;}
function netName(){try{return (store.get('crust-netname')||'').slice(0,14)||RACERS[selected].name;}catch(e){return 'Player';}}
function netLoadLib(){return new Promise((res,rej)=>{if(window.Peer)return res();const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/peerjs@1.5.4/dist/peerjs.min.js';
  const to=setTimeout(()=>rej(new Error('Could not load the multiplayer library. Check your internet connection.')),15000);
  s.onload=()=>{clearTimeout(to);window.Peer?res():rej(new Error('Multiplayer library failed to start.'));};s.onerror=()=>{clearTimeout(to);rej(new Error('Could not load the multiplayer library. Check your internet connection.'));};document.head.appendChild(s);});}
function netReset(){try{for(const c of NET.conns)c.close();}catch(e){}try{if(NET.relay)NET.relay.stop();}catch(e){}NET.relay=null;try{if(NET.peer)NET.peer.destroy();}catch(e){}
  netClearMirrors();Object.assign(NET,{role:null,code:'',peer:null,conns:[],me:0,pl:[],cfg:null,fromNet:false,loaded:new Set(),tick:0,seq:0,hist:[],outQ:[],inQ:{},inS:{},inLast:{},ack:{},snaps:[],fxQ:[],nid:0,finSeen:false});netBadge();}
function netSend(c,m){try{if(c&&c.open)c.send(m);}catch(e){}}
function netAll(m){for(const c of NET.conns)netSend(c,m);}
/* ---------- transport ----------
   Joining and racing go through a public relay (MQTT over a secure WebSocket), which works on Wi-Fi and mobile data alike,
   even when the phones can't reach each other directly. When a direct phone-to-phone link (PeerJS) can also be opened,
   the race data switches to it for lower lag; if it drops, the relay takes over again without anyone noticing. */
