  retry(){if(this.dead)return;clearTimeout(this.rt);if(!this.everOk&&this.tries>5)return;const w=Math.min(500*2**this.tries,5000);this.tries++;this.rt=setTimeout(()=>{if(!this.ws)this.connect().catch(()=>{});},w);}
