function rtcOnGuest(ch,d){if(!ch||!ch.pc||d.id!==ch.rtcId||!d.sdp||d.sdp.type!=='answer')return;if(ch.pc.signalingState==='have-local-offer')ch.pc.setRemoteDescription(d.sdp).catch(()=>{});}
